/**
 * Prints generated files exactly as oxfmt would format them (100 columns, single quotes, trailing
 * commas), so `oxfmt --check` and `nz gen --check` never disagree.
 */

export const HEADER = 'generated by nz gen; do not edit';
export const TS_HEADER = `// ${HEADER}`;

const PRINT_WIDTH = 100;

/** `export { a, b } from './x';`, broken one specifier per line when it does not fit. */
export function exportFrom(specifiers: string[], from: string, typeOnly = false): string {
  const keyword = typeOnly ? 'export type' : 'export';
  const flat = `${keyword} { ${specifiers.join(', ')} } from '${from}';`;
  if (flat.length <= PRINT_WIDTH) return flat;
  return `${keyword} {\n${specifiers.map((specifier) => `  ${specifier},`).join('\n')}\n} from '${from}';`;
}

/** A generated TypeScript module: the header line, then the statements. */
export function tsModule(statements: string[]): string {
  return `${[TS_HEADER, ...statements].join('\n')}\n`;
}

/**
 * JSON in oxfmt's style: objects always expanded, arrays of primitives kept on one line when the
 * line (including a trailing comma) fits in 100 columns.
 */
export function printJson(value: unknown): string {
  return `${printValue(value, 0, 0, 0)}\n`;
}

function printValue(value: unknown, depth: number, column: number, trailing: number): string {
  const inner = '  '.repeat(depth + 1);
  const outer = '  '.repeat(depth);
  if (Array.isArray(value)) {
    if (value.length === 0) return '[]';
    if (value.every((item) => item === null || typeof item !== 'object')) {
      const flat = `[${value.map((item) => JSON.stringify(item)).join(', ')}]`;
      if (column + flat.length + trailing <= PRINT_WIDTH) return flat;
    }
    const items = value.map((item, index) => {
      const comma = index < value.length - 1 ? ',' : '';
      return `${inner}${printValue(item, depth + 1, inner.length, comma.length)}${comma}`;
    });
    return `[\n${items.join('\n')}\n${outer}]`;
  }
  if (typeof value === 'object' && value !== null) {
    const entries = Object.entries(value);
    if (entries.length === 0) return '{}';
    const lines = entries.map(([key, item], index) => {
      const comma = index < entries.length - 1 ? ',' : '';
      const head = `${inner}${JSON.stringify(key)}: `;
      return `${head}${printValue(item, depth + 1, head.length, comma.length)}${comma}`;
    });
    return `{\n${lines.join('\n')}\n${outer}}`;
  }
  return JSON.stringify(value);
}
